steps.cmd:
for s in 59 60 101; do
python3 - <<EOF
score = $s
if not 0 <= score <= 100:
    print(score, "Invalid score")
else:
    if score >= 60:
        print(score, "Pass")
    else:
        print(score, "Fail")
EOF
done

for y in 1900 2000; do
python3 - <<EOF
year = $y
if year <= 0:
    print("Enter a positive year")
elif year % 400 == 0:
    print(f"{year}: Leap year")
elif year % 100 == 0:
    print(f"{year}: Not a leap year")
elif year % 4 == 0:
    print(f"{year}: Leap year")
else:
    print(f"{year}: Not a leap year")
EOF
done
